let celebrationQueue=[],celebrationTimer=null;
function resetCelebration(){clearTimeout(celebrationTimer);celebrationTimer=null;celebrationQueue=[];$('#rarity-celebration').hidden=true;$('#rarity-celebration').innerHTML='';}
function celebrateCard(card){if(!['Epic','Legendary','Archive Foil'].includes(card.rarity))return;celebrationQueue.push(card);if(!celebrationTimer)showNextCelebration();}
function showNextCelebration(){if(!celebrationQueue.length||!$('#opening').open){celebrationTimer=null;$('#rarity-celebration').hidden=true;return;}const card=celebrationQueue.shift(),host=$('#rarity-celebration');host.hidden=false;host.dataset.level=card.rarity;host.innerHTML=`<div class="rarity-orbit"></div><div class="rarity-rays"></div><div class="rarity-sparks" aria-hidden="true">${Array.from({length:18},(_,i)=>`<i style="--spark:${i}"></i>`).join('')}</div><div class="rarity-announcement"><span>${card.rarity==='Archive Foil'?'✳':card.rarity==='Legendary'?'✦':'◆'}</span><strong>${escapeText(card.rarity)}</strong><p>${escapeText(card.name)}</p></div>`;celebrationTimer=setTimeout(()=>{host.hidden=true;celebrationTimer=setTimeout(showNextCelebration,150);},window.matchMedia('(prefers-reduced-motion: reduce)').matches?1200:1900);}
$('#opening').addEventListener('close',resetCelebration);
